sp_widget.client_script:
api.controller = function($scope, $timeout) {
  var c = this;

  // ── Colour palette ──────────────────────────────────
  c.statusColors = ['#5443AD','#10b981','#f59e0b','#ef4444','#06b6d4','#8b5cf6','#f43f5e'];

  // ══════════════════════════════════════════════════════
  // SHARED HELPERS
  // ══════════════════════════════════════════════════════
  c.getPct = function(val, total) {
    if (!total) return 0;
    return Math.round((val / total) * 100);
  };

  c.getDimPct = function(val, dim) {
    var total = (dim.green || 0) + (dim.yellow || 0) + (dim.red || 0);
    if (!total) return 0;
    return Math.max(4, Math.round((val / total) * 100));
  };

  c.countProjects = function(type) {
    if (!c.data.projectProgress) return 0;
    return c.data.projectProgress.filter(function(p) {
      if (type === 'on_track')        return p.percent >= 75;
      if (type === 'in_progress')     return p.percent >= 40 && p.percent < 75;
      if (type === 'needs_attention') return p.percent < 40;
      return false;
    }).length;
  };

  c.avgCompletion = function() {
    if (!c.data.projectProgress || !c.data.projectProgress.length) return 0;
    var sum = c.data.projectProgress.reduce(function(a, p) {
      return a + (p.percent || 0);
    }, 0);
    return Math.round(sum / c.data.projectProgress.length);
  };

  c.psWorstDimension = function() {
    if (!c.data.projectStatusData || !c.data.projectStatusData.dimensions.length)
      return '—';
    var worst = c.data.projectStatusData.dimensions.reduce(function(a, b) {
      return (b.red || 0) > (a.red || 0) ? b : a;
    });
    return (worst.red || 0) > 0 ? worst.label : '—';
  };

  c.psBestDimension = function() {
    if (!c.data.projectStatusData || !c.data.projectStatusData.dimensions.length)
      return '—';
    var best = c.data.projectStatusData.dimensions.reduce(function(a, b) {
      return (b.green || 0) > (a.green || 0) ? b : a;
    });
    return (best.green || 0) > 0 ? best.label : '—';
  };

  c.avgDashArray = function() {
    var avg = c.avgCompletion();
    return avg + ' ' + (100 - avg);
  };

  c.projDashArray = function(pct) {
    var p = Math.max(0, Math.min(100, pct || 0));
    return (p / 100 * 188.5) + ' ' + (188.5 - p / 100 * 188.5);
  };

  c.countAppStatus = function(stateKey) {
    if (!c.data.appStatusChart || !c.data.appStatusChart.labels) return 0;
    var total = 0;
    c.data.appStatusChart.labels.forEach(function(lbl, i) {
      var normalized = lbl.toLowerCase().replace(/[\s_]+/g, '_');
      var key        = stateKey.toLowerCase().replace(/[\s_]+/g, '_');
      if (normalized.indexOf(key) !== -1 || key.indexOf(normalized) !== -1) {
        total += (c.data.appStatusChart.counts[i] || 0);
      }
    });
    return total;
  };

  c.srTotal = function() {
    if (!c.data.statusReports) return 0;
    return c.data.statusReports.reduce(function(a, r) { return a + r.count; }, 0);
  };
  c.srAvg = function() {
    if (!c.data.statusReports || !c.data.statusReports.length) return 0;
    return (c.srTotal() / c.data.statusReports.length).toFixed(1);
  };
  c.srMax = function() {
    if (!c.data.statusReports || !c.data.statusReports.length) return 0;
    return Math.max.apply(null, c.data.statusReports.map(function(r) { return r.count; }));
  };

  c.getBadgeClass = function(state) {
    if (!state) return 'badge-draft';
    var map = {
      'under_review':       'badge-review',
      'draft':              'badge-draft',
      'approved':           'badge-approved',
      'submitted':          'badge-submitted',
      'rejected':           'badge-rejected',
      'declined_by_agency': 'badge-rejected',
      'ready_for_review':   'badge-review'
    };
    return map[state.toLowerCase()] || 'badge-draft';
  };

  try {
    angular.module('sn.cs.widget').filter('capitalize', function() {
      return function(input) {
        if (!input) return '';
        var s = input.toString();
        return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
      };
    });
  } catch(e) { /* already registered — ignore */ }

  // ══════════════════════════════════════════════════════
  // CHART DRAWING
  // ══════════════════════════════════════════════════════
  c.drawCharts = function() { drawCharts(); };

  function drawCharts() {
    if (typeof Chart === 'undefined') {
      $timeout(drawCharts, 350);
      return;
    }

    var COLORS = ['#5443AD','#10b981','#f59e0b','#ef4444','#06b6d4','#8b5cf6','#f43f5e'];
    var ROSE   = '#f43f5e';
    var GRID   = 'rgba(0,0,0,0.05)';
    var TEXT   = '#6b7280';
    var DARK   = '#1e1e2e';
    var font   = { family: "'Inter','Segoe UI',sans-serif", size: 12, weight: '500' };

    var tooltipDefaults = {
      backgroundColor: DARK,
      titleColor:      '#fff',
      bodyColor:       '#d1d5db',
      padding:         12,
      cornerRadius:    10,
      displayColors:   true,
      boxWidth:        10,
      boxHeight:       10,
      boxPadding:      4,
      titleFont: { family: font.family, size: 13, weight: '700' },
      bodyFont:  { family: font.family, size: 12 }
    };

    // ── CHART 1 — APPLICATION PIPELINE ──
    var appCtx = document.getElementById('appStatusChart');
    if (appCtx && c.data.appStatusChart && c.data.appStatusChart.labels.length) {
      var d        = c.data.appStatusChart;
      var total_ap = d.counts.reduce(function(a, b) { return a + b; }, 0);
      new Chart(appCtx, {
        type: 'doughnut',
        data: {
          labels: d.labels,
          datasets: [{
            data:             d.counts,
            backgroundColor:  d.labels.map(function(_, i) { return COLORS[i % COLORS.length]; }),
            borderColor:      '#f8fafc',
            borderWidth:      4,
            hoverOffset:      16,
            hoverBorderWidth: 0,
            borderRadius:     6
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          cutout: '70%', rotation: -90,
          animation: { animateRotate: true, duration: 1200, easing: 'easeOutQuart' },
          plugins: {
            legend:  { display: false },
            tooltip: Object.assign({}, tooltipDefaults, {
              callbacks: {
                label: function(ctx) {
                  var pct = total_ap ? Math.round((ctx.parsed / total_ap) * 100) : 0;
                  return '  ' + ctx.label + ':  ' + ctx.parsed + '  (' + pct + '%)';
                }
              }
            })
          }
        },
        plugins: [{
          beforeDraw: function(chart) {
            var w = chart.width, h = chart.height, cx = chart.ctx;
            cx.restore();
            cx.font = 'bold 28px Inter,sans-serif'; cx.fillStyle = DARK;
            cx.textAlign = 'center'; cx.textBaseline = 'middle';
            cx.fillText(total_ap, w / 2, h / 2 - 10);
            cx.font = '600 10px Inter,sans-serif'; cx.fillStyle = TEXT;
            cx.fillText('APPLICATIONS', w / 2, h / 2 + 12);
            cx.save();
          }
        }]
      });
    }

    // ── CHART 2 — REIMBURSEMENTS ──
    var rCtx = document.getElementById('reimbursementChart');
    if (rCtx && c.data.reimbursementStats && c.data.reimbursementStats.total) {
      var ri      = c.data.reimbursementStats;
      var total_r = ri.total;
      new Chart(rCtx, {
        type: 'doughnut',
        data: {
          labels: ri.items.map(function(i) { return i.label; }),
          datasets: [{
            data:             ri.items.map(function(i) { return i.count; }),
            backgroundColor:  ri.items.map(function(i) { return i.color; }),
            borderColor:      '#fff', borderWidth: 3,
            hoverOffset: 14, hoverBorderWidth: 0
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          cutout: '72%',
          animation: { animateRotate: true, duration: 1000, easing: 'easeOutQuart' },
          plugins: {
            legend:  { display: false },
            tooltip: Object.assign({}, tooltipDefaults, {
              callbacks: {
                label: function(ctx) {
                  var pct = Math.round((ctx.parsed / total_r) * 100);
                  return '  ' + ctx.label + ': ' + ctx.parsed + ' (' + pct + '%)';
                }
              }
            })
          }
        },
        plugins: [{
          beforeDraw: function(chart) {
            var w = chart.width, h = chart.height, cx = chart.ctx;
            cx.restore();
            cx.font = 'bold 26px Inter,sans-serif'; cx.fillStyle = DARK;
            cx.textAlign = 'center'; cx.textBaseline = 'middle';
            cx.fillText(total_r, w / 2, h / 2 - 10);
            cx.font = '600 11px Inter,sans-serif'; cx.fillStyle = TEXT;
            cx.fillText('FILED', w / 2, h / 2 + 12);
            cx.save();
          }
        }]
      });
    }

    // ── CHART 3 — STATUS REPORT TIMELINE ──
    var srCtx = document.getElementById('statusReportChart');
    if (srCtx && c.data.statusReports && c.data.statusReports.length) {
      var sr     = c.data.statusReports;
      var srCvs  = srCtx.getContext('2d');
      var srGrad = srCvs.createLinearGradient(0, 0, 0, 210);
      srGrad.addColorStop(0,   ROSE + '60');
      srGrad.addColorStop(0.5, ROSE + '25');
      srGrad.addColorStop(1,   ROSE + '00');
      new Chart(srCtx, {
        type: 'line',
        data: {
          labels: sr.map(function(r) { return r.month; }),
          datasets: [{
            label: 'Reports', data: sr.map(function(r) { return r.count; }),
            borderColor: ROSE, backgroundColor: srGrad,
            borderWidth: 3, fill: true, tension: 0.45,
            pointBackgroundColor: ROSE, pointBorderColor: '#fff',
            pointBorderWidth: 3, pointRadius: 6, pointHoverRadius: 10,
            pointHoverBackgroundColor: '#fff',
            pointHoverBorderColor: ROSE, pointHoverBorderWidth: 3
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          animation:   { duration: 1000, easing: 'easeOutQuart' },
          interaction: { mode: 'index', intersect: false },
          plugins: {
            legend:  { display: false },
            tooltip: Object.assign({}, tooltipDefaults, {
              callbacks: {
                title: function(items) { return items[0].label; },
                label: function(ctx) {
                  return '  ' + ctx.parsed.y + ' report' + (ctx.parsed.y !== 1 ? 's' : '') + ' submitted';
                }
              }
            })
          },
          scales: {
            x: { grid: { display: false }, ticks: { color: TEXT, font: font } },
            y: { grid: { color: GRID, drawBorder: false }, ticks: { color: TEXT, font: font, stepSize: 1, padding: 8 }, beginAtZero: true }
          }
        },
        plugins: [{
          afterDraw: function(chart) {
            if (chart.tooltip._active && chart.tooltip._active.length) {
              var cx = chart.ctx;
              var x  = chart.tooltip._active[0].element.x;
              cx.save();
              cx.beginPath();
              cx.moveTo(x, chart.chartArea.top);
              cx.lineTo(x, chart.chartArea.bottom);
              cx.lineWidth = 1.5; cx.strokeStyle = 'rgba(244,63,94,0.3)';
              cx.setLineDash([4, 4]); cx.stroke();
              cx.restore();
            }
          }
        }]
      });
    }

    // ── CHART 4 — PROJECT STATUS RADAR ──
    var radarCtx = document.getElementById('projectStatusRadar');
    if (radarCtx && c.data.projectStatusData && c.data.projectStatusData.dimensions.length) {
      var dims    = c.data.projectStatusData.dimensions;
      var rLabels = dims.map(function(d) { return d.label; });
      new Chart(radarCtx, {
        type: 'radar',
        data: {
          labels: rLabels,
          datasets: [
            {
              label: 'Green', data: dims.map(function(d) { return d.green  || 0; }),
              borderColor: '#10b981', backgroundColor: 'rgba(16,185,129,0.15)',
              borderWidth: 2.5, pointBackgroundColor: '#10b981',
              pointBorderColor: '#fff', pointBorderWidth: 2, pointRadius: 5, pointHoverRadius: 8
            },
            {
              label: 'Yellow', data: dims.map(function(d) { return d.yellow || 0; }),
              borderColor: '#f59e0b', backgroundColor: 'rgba(245,158,11,0.12)',
              borderWidth: 2.5, pointBackgroundColor: '#f59e0b',
              pointBorderColor: '#fff', pointBorderWidth: 2, pointRadius: 5, pointHoverRadius: 8
            },
            {
              label: 'Red', data: dims.map(function(d) { return d.red    || 0; }),
              borderColor: '#ef4444', backgroundColor: 'rgba(239,68,68,0.1)',
              borderWidth: 2.5, pointBackgroundColor: '#ef4444',
              pointBorderColor: '#fff', pointBorderWidth: 2, pointRadius: 5, pointHoverRadius: 8
            }
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          animation:  { duration: 900, easing: 'easeOutQuart' },
          scales: {
            r: {
              beginAtZero: true,
              ticks:       { stepSize: 1, color: TEXT, font: font, backdropColor: 'transparent' },
              grid:        { color: 'rgba(0,0,0,0.07)' },
              angleLines:  { color: 'rgba(0,0,0,0.07)' },
              pointLabels: { color: DARK, font: { family: font.family, size: 12, weight: '600' } }
            }
          },
          plugins: {
            legend: {
              display: true, position: 'bottom',
              labels: { color: TEXT, font: font, boxWidth: 12, padding: 16, usePointStyle: true }
            },
            tooltip: Object.assign({}, tooltipDefaults, {
              callbacks: {
                label: function(ctx) { return '  ' + ctx.dataset.label + ': ' + ctx.parsed.r; }
              }
            })
          }
        }
      });
    }

    // ── CHART 5 — PROJECT STATUS GROUPED BAR ──
    var gbCtx = document.getElementById('projectStatusGroupedBar');
    if (gbCtx && c.data.projectStatusData && c.data.projectStatusData.dimensions.length) {
      var gbDims = c.data.projectStatusData.dimensions;
      new Chart(gbCtx, {
        type: 'bar',
        data: {
          labels: gbDims.map(function(d) { return d.label; }),
          datasets: [
            {
              label: 'Green', data: gbDims.map(function(d) { return d.green  || 0; }),
              backgroundColor: 'rgba(16,185,129,0.85)', borderWidth: 0,
              borderRadius: { topLeft: 6, topRight: 6 }, borderSkipped: false
            },
            {
              label: 'Yellow', data: gbDims.map(function(d) { return d.yellow || 0; }),
              backgroundColor: 'rgba(245,158,11,0.85)', borderWidth: 0,
              borderRadius: { topLeft: 6, topRight: 6 }, borderSkipped: false
            },
            {
              label: 'Red', data: gbDims.map(function(d) { return d.red    || 0; }),
              backgroundColor: 'rgba(239,68,68,0.85)', borderWidth: 0,
              borderRadius: { topLeft: 6, topRight: 6 }, borderSkipped: false
            }
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          animation: {
            duration: 900, easing: 'easeOutQuart',
            delay: function(ctx) { return ctx.dataIndex * 80; }
          },
          interaction: { mode: 'index', intersect: false },
          plugins: {
            legend: {
              display: true, position: 'top', align: 'end',
              labels: { color: TEXT, font: font, boxWidth: 12, padding: 16, usePointStyle: true }
            },
            tooltip: Object.assign({}, tooltipDefaults)
          },
          scales: {
            x: { grid: { display: false }, ticks: { color: DARK, font: { family: font.family, size: 12, weight: '600' } } },
            y: { grid: { color: GRID, drawBorder: false }, ticks: { color: TEXT, font: font, stepSize: 1, padding: 6 }, beginAtZero: true }
          }
        }
      });
    }

    // ── CHART 6a — CHANGE REQUESTS: Priority Doughnut ──
    var crCtx = document.getElementById('changeRequestChart');
    if (crCtx && c.data.changeRequestStats && c.data.changeRequestStats.total) {
      var cri      = c.data.changeRequestStats;
      var pri      = cri.byPriority;
      var total_cr = cri.total;
      new Chart(crCtx, {
        type: 'doughnut',
        data: {
          labels: pri.map(function(i) { return i.label; }),
          datasets: [{
            data:            pri.map(function(i) { return i.count; }),
            backgroundColor: pri.map(function(i) { return i.color; }),
            borderColor: '#fff', borderWidth: 3,
            hoverOffset: 12, hoverBorderWidth: 0
          }]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          cutout: '70%',
          animation: { animateRotate: true, duration: 1000 },
          plugins: {
            legend:  { display: false },
            tooltip: Object.assign({}, tooltipDefaults, {
              callbacks: {
                label: function(ctx) {
                  var pct = Math.round((ctx.parsed / total_cr) * 100);
                  return '  ' + ctx.label + ': ' + ctx.parsed + ' (' + pct + '%)';
                }
              }
            })
          }
        },
        plugins: [{
          beforeDraw: function(chart) {
            var w = chart.width, h = chart.height, cx = chart.ctx;
            cx.restore();
            cx.font = 'bold 22px Inter,sans-serif'; cx.fillStyle = DARK;
            cx.textAlign = 'center'; cx.textBaseline = 'middle';
            cx.fillText(total_cr, w / 2, h / 2 - 9);
            cx.font = '600 11px Inter,sans-serif'; cx.fillStyle = TEXT;
            cx.fillText('TOTAL', w / 2, h / 2 + 11);
            cx.save();
          }
        }]
      });
    }

    // ── CHART 6b — CHANGE REQUESTS: Category Horizontal Bar ──
    var crCatCtx = document.getElementById('changeRequestCategoryChart');
    if (crCatCtx && c.data.changeRequestStats &&
        c.data.changeRequestStats.byCategory &&
        c.data.changeRequestStats.byCategory.length) {
      var cats = c.data.changeRequestStats.byCategory;
      new Chart(crCatCtx, {
        type: 'bar',
        data: {
          labels: cats.map(function(item) { return item.label; }),
          datasets: [{
            label: 'Count',
            data:  cats.map(function(item) { return item.count; }),
            backgroundColor: cats.map(function(item) {
              var g = crCatCtx.getContext('2d')
                        .createLinearGradient(0, 0, crCatCtx.offsetWidth || 300, 0);
              g.addColorStop(0, item.color);
              g.addColorStop(1, item.color + '88');
              return g;
            }),
            borderColor: 'transparent', borderRadius: 8,
            borderSkipped: false, barThickness: 18
          }]
        },
        options: {
          indexAxis: 'y', responsive: true, maintainAspectRatio: false,
          animation: { duration: 800, easing: 'easeOutQuart' },
          plugins: {
            legend:  { display: false },
            tooltip: Object.assign({}, tooltipDefaults, {
              callbacks: {
                label: function(ctx) {
                  return '  ' + ctx.parsed.x + ' request' + (ctx.parsed.x !== 1 ? 's' : '');
                }
              }
            })
          },
          scales: {
            x: { grid: { color: GRID, drawBorder: false }, ticks: { color: TEXT, font: font, stepSize: 1 }, beginAtZero: true },
            y: { grid: { display: false }, ticks: { color: DARK, font: { family: font.family, size: 11, weight: '600' } } }
          }
        },
        plugins: [{
          afterDatasetsDraw: function(chart) {
            var cx = chart.ctx;
            chart.data.datasets[0].data.forEach(function(val, i) {
              var meta = chart.getDatasetMeta(0);
              var bar  = meta.data[i];
              cx.save();
              cx.fillStyle    = cats[i] ? cats[i].color : DARK;
              cx.font         = 'bold 11px Inter,sans-serif';
              cx.textAlign    = 'left'; cx.textBaseline = 'middle';
              cx.fillText(val, bar.x + 6, bar.y);
              cx.restore();
            });
          }
        }]
      });
    }

    // ── CHART 7 — PROJECT COMPLETION PIE ──
    (function() {
      if (!c.data.projectProgress || !c.data.projectProgress.length) return;
      var projects = c.data.projectProgress;
      var PALETTE  = ['#6366f1','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4','#f43f5e','#84cc16'];
      c.pcdColor   = function(idx) { return PALETTE[idx % PALETTE.length]; };
      var el = document.getElementById('pcdPie');
      if (!el) return;
      new Chart(el.getContext('2d'), {
        type: 'pie',
        data: {
          labels: projects.map(function(p) { return p.name; }),
          datasets: [{
            data:                 projects.map(function(p) { return Math.max(p.percent || 0, 3); }),
            backgroundColor:      projects.map(function(_, i) { return PALETTE[i % PALETTE.length] + 'cc'; }),
            hoverBackgroundColor: projects.map(function(_, i) { return PALETTE[i % PALETTE.length]; }),
            borderColor:          '#f8fafc',
            borderWidth:          5,
            hoverOffset:          18,
            borderRadius:         6
          }]
        },
        options: {
          responsive: false, maintainAspectRatio: false,
          animation: { animateRotate: true, animateScale: true, duration: 1600, easing: 'easeOutBack' },
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.93)',
              titleFont: { size: 12, weight: '800', family: 'Inter,sans-serif' },
              bodyFont:  { size: 11, family: 'Inter,sans-serif' },
              padding: 12, cornerRadius: 10,
              displayColors: true, boxWidth: 9, boxHeight: 9, boxPadding: 4,
              callbacks: {
                title: function(items) { return projects[items[0].dataIndex].name; },
                label: function(ctx) {
                  var p = projects[ctx.dataIndex];
                  var s = p.percent >= 75 ? '✅ On Track' : p.percent >= 40 ? '⏳ In Progress' : p.percent > 0 ? '🔴 At Risk' : '⬜ Not Started';
                  return [
                    '  Completion : ' + (p.percent || 0) + '%',
                    '  Phase      : ' + (p.phase || '—'),
                    '  Status     : ' + s
                  ];
                }
              }
            }
          }
        },
        plugins: []
      });
    })();

  } // end drawCharts()

  $timeout(drawCharts, 500);
};

sp_widget.css:
/* ════════════════════════════════════════
   RESET & LAYOUT
════════════════════════════════════════ */
.gn-layout {
  margin-left: -15px;
  margin-right: -15px;
  margin-top: 35px;
  display: flex;
  align-items: stretch;          /* ← was flex-start */
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #f0f2f8;
  width: calc(100% + 30px);
  position: relative;
  min-height: 100vh;
}
.gn-layout *, .gn-layout *:before, .gn-layout *:after {
  box-sizing: border-box;
}
.sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #fff;
  border-right: 1px solid #e5e7eb;

  /* Stick to viewport top, full height, no inner scroll */
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;          /* only scrolls if content overflows */
  overflow-x: hidden;
  overscroll-behavior: contain;
  z-index: 10;

  /* Remove any gap below */
  align-self: flex-start;
}
.gn-main {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #f0f2f8;
  padding: 24px 28px 48px;
  flex: 1;
  min-width: 0;              /* ← prevents flex overflow */
  min-height: 100vh;
}

/* ════════════════════════════════════════
   HERO BANNER
════════════════════════════════════════ */
.gn-banner {
  background: linear-gradient(135deg, #2d2669 0%, #4a3fa0 45%, #6b5fd4 100%);
  border-radius: 20px;
  padding: 40px 52px 32px;
  display: flex;
  flex-direction: column;
  gap: 28px;
  margin-bottom: 28px;
  color: #fff;
  min-height: 190px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 8px 32px rgba(84,67,173,0.25);
}
.gn-banner::before {
  content: ''; position: absolute; top: -60px; right: -60px;
  width: 260px; height: 260px; background: rgba(255,255,255,0.05); border-radius: 50%;
}
.gn-banner::after {
  content: ''; position: absolute; bottom: -80px; right: 120px;
  width: 200px; height: 200px; background: rgba(255,255,255,0.04); border-radius: 50%;
}
.gn-banner-top  { display: flex; flex-direction: column; position: relative; z-index: 1; }
.gn-banner h2   { margin: 0 0 10px; font-size: 30px; font-weight: 800; color: #fff; letter-spacing: -0.5px; }
.gn-banner p    { margin: 0; font-size: 14px; opacity: 0.85; color: #e8e6ff; line-height: 1.6; }
.gn-banner-btns { display: flex; gap: 12px; flex-wrap: wrap; position: relative; z-index: 1; }

.btn-primary {
  background: #fff; color: #4a3fa0; font-weight: 700; padding: 11px 22px;
  border-radius: 10px; text-decoration: none; font-size: 13px;
  display: inline-flex; align-items: center; gap: 7px;
  transition: transform 0.15s, box-shadow 0.15s;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
}
.btn-primary:hover {
  background: #EEEDFB; text-decoration: none; color: #4a3fa0;
  transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.15);
}
.btn-outline {
  border: 2px solid rgba(255,255,255,0.6); color: #fff; padding: 10px 22px;
  border-radius: 10px; text-decoration: none; font-size: 13px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 7px;
  backdrop-filter: blur(4px); transition: all 0.15s;
}
.btn-outline:hover {
  background: rgba(255,255,255,0.18); text-decoration: none;
  color: #fff; transform: translateY(-1px);
}

/* ════════════════════════════════════════
   KPI CARDS
════════════════════════════════════════ */
.gn-cards { display: grid; grid-template-columns: repeat(3,1fr); gap: 18px; margin-bottom: 24px; }
.gn-card-new {
  background: #fff; border-radius: 16px; padding: 20px 20px 0;
  display: flex; flex-direction: column; gap: 12px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06); border: 1px solid #ebebf5;
  overflow: hidden; min-height: 148px; position: relative;
}
.gn-card-new-header { display: flex; justify-content: space-between; align-items: flex-start; }
.gn-card-new-icon {
  width: 44px; height: 44px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center; font-size: 18px;
}
.gn-card-new-icon.blue   { background: linear-gradient(135deg,#EEEDFB,#dddaf7); color: #5443AD; }
.gn-card-new-icon.orange { background: linear-gradient(135deg,#fff7ed,#ffe8d0); color: #ea580c; }
.gn-card-new-icon.green  { background: linear-gradient(135deg,#f0fdf4,#d1fae5); color: #10b981; }
.gn-badge-pill {
  font-size: 11px; font-weight: 600; padding: 4px 10px;
  border-radius: 20px; display: inline-flex; align-items: center; gap: 4px;
}
.gn-badge-blue   { background: #EEEDFB; color: #5443AD; }
.gn-badge-orange { background: #fff7ed; color: #ea580c; }
.gn-badge-green  { background: #f0fdf4; color: #10b981; }
.gn-card-new-body { display: flex; flex-direction: column; gap: 2px; padding-bottom: 16px; }
.gn-card-new-val  { font-size: 36px; font-weight: 800; color: #1e1e2e; line-height: 1; }
.gn-card-new-lbl  { font-size: 13px; color: #6b7280; margin-top: 4px; font-weight: 500; }
.gn-card-new-bar  { height: 4px; background: #f1f5f9; position: relative; margin-top: auto; }
.gn-card-new-bar::after {
  content: ''; position: absolute; left: 0; top: 0; height: 100%;
  width: var(--pct,0%); background: var(--clr,#5443AD);
  border-radius: 0 2px 2px 0; transition: width 1s ease;
}

/* ════════════════════════════════════════
   ANALYTICS CARDS
════════════════════════════════════════ */
.gn-analytics-card {
  background: #fff; border-radius: 18px; overflow: hidden;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07); border: 1px solid #ebebf5;
}
.gn-analytics-card--full { width: 100%; }
.gn-analytics-hdr {
  padding: 18px 24px; display: flex;
  justify-content: space-between; align-items: center; color: #fff;
  flex-wrap: wrap; gap: 10px;
}
.gn-analytics-hdr--purple { background: linear-gradient(135deg,#4a3fa0,#6b5fd4); }
.gn-analytics-hdr--teal   { background: linear-gradient(135deg,#0d7a6e,#10b981); }
.gn-analytics-hdr--indigo { background: linear-gradient(135deg,#3730a3,#6366f1); }
.gn-analytics-hdr--amber  { background: linear-gradient(135deg,#b45309,#f59e0b); }
.gn-analytics-hdr--rose   { background: linear-gradient(135deg,#9f1239,#f43f5e); }
.gn-analytics-title {
  font-size: 15px; font-weight: 700; color: #fff;
  display: flex; align-items: center; gap: 8px;
}
.gn-analytics-sub   { font-size: 12px; color: rgba(255,255,255,0.75); margin-top: 3px; }
.gn-analytics-badge {
  background: rgba(255,255,255,0.2); color: #fff; font-size: 12px;
  font-weight: 700; padding: 5px 14px; border-radius: 20px;
  backdrop-filter: blur(4px); border: 1px solid rgba(255,255,255,0.25);
  white-space: nowrap; flex-shrink: 0;
}
.gn-analytics-body { padding: 20px 24px 24px; }

/* ════════════════════════════════════════
   CHART WRAPPERS
════════════════════════════════════════ */
.gn-chart-wrap { position: relative; display: block; }
.gn-chart-wrap canvas { display: block !important; }

/* ════════════════════════════════════════
   GRID + COLOR UTILITIES
════════════════════════════════════════ */
.gn-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.blue-text   { color: #5443AD !important; }
.orange-text { color: #ea580c !important; }
.green-text  { color: #10b981 !important; }

/* ════════════════════════════════════════
   APPLICATION PIPELINE
════════════════════════════════════════ */
.gn-ap-hdr-stat {
  display: inline-flex; align-items: center; gap: 5px;
  background: rgba(255,255,255,0.15); color: #fff;
  font-size: 12px; font-weight: 600;
  padding: 5px 12px; border-radius: 20px;
  border: 1px solid rgba(255,255,255,0.2);
  backdrop-filter: blur(4px);
}
.gn-ap-hdr-stat--warn { background: rgba(245,158,11,0.25); border-color: rgba(245,158,11,0.4); }
.gn-ap-body { padding: 22px 24px 24px; }

.gn-ap-kpi-row {
  display: grid; grid-template-columns: repeat(4,1fr);
  gap: 12px; margin-bottom: 22px;
}
.gn-ap-kpi {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 16px; border-radius: 14px;
  border: 1.5px solid transparent;
  position: relative; overflow: hidden;
  transition: transform 0.15s, box-shadow 0.15s; cursor: default;
}
.gn-ap-kpi:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.1); }
.gn-ap-kpi::before {
  content: ''; position: absolute; top: -30px; right: -30px;
  width: 90px; height: 90px; border-radius: 50%;
  background: rgba(255,255,255,0.08);
}
.gn-ap-kpi--blue   { background: linear-gradient(135deg,#EEEDFB,#dddaf7); border-color: #c4bff5; }
.gn-ap-kpi--green  { background: linear-gradient(135deg,#f0fdf4,#dcfce7); border-color: #bbf7d0; }
.gn-ap-kpi--amber  { background: linear-gradient(135deg,#fffbeb,#fef3c7); border-color: #fde68a; }
.gn-ap-kpi--red    { background: linear-gradient(135deg,#fef2f2,#fee2e2); border-color: #fca5a5; }
.gn-ap-kpi-icon {
  width: 40px; height: 40px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 17px; flex-shrink: 0;
}
.gn-ap-kpi--blue  .gn-ap-kpi-icon { background: rgba(84,67,173,0.12);  color: #5443AD; }
.gn-ap-kpi--green .gn-ap-kpi-icon { background: rgba(16,185,129,0.12); color: #10b981; }
.gn-ap-kpi--amber .gn-ap-kpi-icon { background: rgba(245,158,11,0.12); color: #d97706; }
.gn-ap-kpi--red   .gn-ap-kpi-icon { background: rgba(239,68,68,0.12);  color: #dc2626; }
.gn-ap-kpi-info { flex: 1; min-width: 0; }
.gn-ap-kpi-info strong { display: block; font-size: 28px; font-weight: 800; line-height: 1; }
.gn-ap-kpi--blue  .gn-ap-kpi-info strong { color: #5443AD; }
.gn-ap-kpi--green .gn-ap-kpi-info strong { color: #16a34a; }
.gn-ap-kpi--amber .gn-ap-kpi-info strong { color: #b45309; }
.gn-ap-kpi--red   .gn-ap-kpi-info strong { color: #dc2626; }
.gn-ap-kpi-info span { font-size: 11px; font-weight: 600; color: #6b7280; margin-top: 3px; display: block; }

.gn-ap-mid { display: flex; gap: 24px; align-items: flex-start; }
.gn-ap-section-label {
  font-size: 10px; font-weight: 700; color: #9ca3af;
  text-transform: uppercase; letter-spacing: 0.7px;
  margin-bottom: 14px; display: flex; align-items: center; gap: 5px;
}
.gn-ap-funnel {
  flex: 1; min-width: 0; background: #f8fafc;
  border-radius: 16px; padding: 18px 20px; border: 1px solid #ebebf5;
}
.gn-ap-funnel-list  { display: flex; flex-direction: column; gap: 10px; margin-bottom: 18px; }
.gn-ap-funnel-row   { display: flex; align-items: center; gap: 10px; }
.gn-ap-funnel-meta  { display: flex; align-items: center; gap: 7px; width: 140px; flex-shrink: 0; }
.gn-ap-funnel-dot   { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
.gn-ap-funnel-lbl   { font-size: 12px; font-weight: 600; color: #374151; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gn-ap-funnel-track { flex: 1; height: 32px; background: #e9ecf4; border-radius: 10px; overflow: hidden; position: relative; }
.gn-ap-funnel-fill  {
  height: 100%; border-radius: 10px;
  display: flex; align-items: center; justify-content: flex-end;
  min-width: 28px; transition: width 1.4s cubic-bezier(0.4,0,0.2,1); position: relative;
}
.gn-ap-funnel-fill::after {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,0.18));
  border-radius: 10px;
}
.gn-ap-funnel-fill-pct {
  font-size: 11px; font-weight: 800; color: #fff;
  padding-right: 10px; position: relative; z-index: 1; white-space: nowrap;
  text-shadow: 0 1px 3px rgba(0,0,0,0.25);
}
.gn-ap-funnel-count { width: 28px; text-align: right; flex-shrink: 0; font-size: 15px; font-weight: 800; }
.gn-ap-conv-strip {
  display: flex; align-items: center;
  background: #fff; border-radius: 12px; padding: 12px 16px; border: 1px solid #ebebf5;
}
.gn-ap-conv-item  { flex: 1; text-align: center; }
.gn-ap-conv-label { display: block; font-size: 10px; font-weight: 600; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.4px; margin-bottom: 4px; }
.gn-ap-conv-val   { font-size: 20px; font-weight: 800; }
.gn-ap-conv-sep   { width: 1px; height: 36px; background: #e5e7eb; flex-shrink: 0; margin: 0 8px; }
.gn-ap-donut-wrap {
  width: 340px; flex-shrink: 0; background: #f8fafc;
  border-radius: 16px; padding: 18px 20px; border: 1px solid #ebebf5;
}
.gn-ap-donut-inner  { display: flex; gap: 16px; align-items: center; }
.gn-ap-donut-legend { flex: 1; display: flex; flex-direction: column; gap: 8px; }
.gn-ap-leg-item {
  display: flex; align-items: center; gap: 8px;
  padding: 7px 10px; background: #fff; border-radius: 10px;
  border: 1px solid #f1f5f9; transition: box-shadow 0.15s;
}
.gn-ap-leg-item:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.07); }
.gn-ap-leg-dot   { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
.gn-ap-leg-lbl   { flex: 1; font-size: 11px; font-weight: 600; color: #374151; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gn-ap-leg-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.gn-ap-leg-pct   { font-size: 12px; font-weight: 800; }
.gn-ap-leg-count { font-size: 12px; font-weight: 700; color: #9ca3af; min-width: 16px; text-align: right; }

/* ══════════════════════════════════════════════
   PROJECT COMPLETION  v19
   Single-column · Pie centre · Mixed-metric legend
══════════════════════════════════════════════ */
.pcd-card {
  font-family:'Inter','Segoe UI',system-ui,sans-serif;
  background:#fff;
  border-radius:20px;
  border:1px solid #e2e8f0;
  box-shadow:0 4px 28px rgba(0,0,0,0.07);
  overflow:hidden;
}

/* ── Header ── */
.pcd-header {
  display:flex; align-items:center;
  justify-content:space-between; flex-wrap:wrap; gap:10px;
  padding:15px 20px;
  background:linear-gradient(135deg,#064e3b 0%,#059669 52%,#10b981 100%);
  position:relative; overflow:hidden;
}
.pcd-header::before {
  content:''; position:absolute; top:-40px; right:-20px;
  width:130px; height:130px; border-radius:50%;
  background:rgba(255,255,255,0.07); pointer-events:none;
}
.pcd-hd-left  { display:flex; align-items:center; gap:10px; position:relative; z-index:1; }
.pcd-hd-icon  {
  width:38px; height:38px; border-radius:10px;
  background:rgba(255,255,255,0.15); border:1px solid rgba(255,255,255,0.2);
  display:flex; align-items:center; justify-content:center;
  color:#fff; font-size:15px; flex-shrink:0;
}
.pcd-hd-title { font-size:15px; font-weight:800; color:#fff; }
.pcd-hd-sub   { font-size:10px; color:rgba(255,255,255,0.65); margin-top:2px; }
.pcd-hd-pills { display:flex; gap:6px; flex-wrap:wrap; position:relative; z-index:1; }
.pcd-pill {
  display:inline-flex; align-items:center; gap:5px;
  font-size:10px; font-weight:700; padding:5px 12px;
  border-radius:99px; color:#fff; white-space:nowrap;
  border:1px solid rgba(255,255,255,0.2);
}
.pcd-pill i  { font-size:8px; }
.pcd-pill--g { background:rgba(16,185,129,0.35); }
.pcd-pill--y { background:rgba(245,158,11,0.40); }
.pcd-pill--r { background:rgba(239,68,68,0.40); }

/* ── Body ── */
.pcd-body {
  padding:14px 16px 18px;
  display:flex; flex-direction:column; gap:14px;
}

/* ── KPI strip — icon left, number right, no truncation ── */
.pcd-kpi-strip {
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:8px;
}
.pcd-kpi {
  display:flex; align-items:center; gap:10px;
  padding:10px 12px; border-radius:13px;
  min-width:0; overflow:hidden;
  transition:transform .15s,box-shadow .15s;
}
.pcd-kpi:hover { transform:translateY(-2px); box-shadow:0 4px 14px rgba(0,0,0,0.08); }
.pcd-kpi--purple { background:linear-gradient(135deg,#f5f3ff,#ede9fe); border:1px solid #ddd6fe; }
.pcd-kpi--teal   { background:linear-gradient(135deg,#ecfdf5,#d1fae5); border:1px solid #a7f3d0; }
.pcd-kpi--amber  { background:linear-gradient(135deg,#fffbeb,#fef3c7); border:1px solid #fde68a; }
.pcd-kpi--red    { background:linear-gradient(135deg,#fff5f5,#fee2e2); border:1px solid #fecaca; }
.pcd-kpi-ic {
  width:30px; height:30px; border-radius:8px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center; font-size:12px;
}
.pcd-kpi--purple .pcd-kpi-ic { background:rgba(124,58,237,0.12); color:#7c3aed; }
.pcd-kpi--teal   .pcd-kpi-ic { background:rgba(5,150,105,0.12);  color:#059669; }
.pcd-kpi--amber  .pcd-kpi-ic { background:rgba(217,119,6,0.12);  color:#d97706; }
.pcd-kpi--red    .pcd-kpi-ic { background:rgba(220,38,38,0.12);  color:#dc2626; }
.pcd-kpi-val  { font-size:20px; font-weight:900; line-height:1; letter-spacing:-0.5px; white-space:nowrap; }
.pcd-kpi-u    { font-size:11px; font-weight:700; opacity:.7; }
.pcd-kpi--purple .pcd-kpi-val { color:#7c3aed; }
.pcd-kpi--teal   .pcd-kpi-val { color:#059669; }
.pcd-kpi--amber  .pcd-kpi-val { color:#d97706; }
.pcd-kpi--red    .pcd-kpi-val { color:#dc2626; }
.pcd-kpi-lbl  { font-size:9px; font-weight:600; color:#6b7280; margin-top:1px; white-space:nowrap; }

/* ── Pie chart area — centered, full width ── */
.pcd-chart-area {
  display:flex; justify-content:center; align-items:center;
  background:#f8fafc; border:1px solid #f1f5f9;
  border-radius:16px; padding:18px;
}
.pcd-chart-area canvas {
  display:block !important;
  width:220px !important; height:220px !important;
}

/* ── Mixed-metric legend rows ── */
.pcd-legend {
  display:flex; flex-direction:column; gap:8px;
}

.pcd-leg-row {
  display:grid;
  grid-template-columns: 32px 1fr 120px 56px;
  align-items:center;
  gap:10px;
  padding:9px 12px;
  background:#f8fafc;
  border:1px solid #f1f5f9;
  border-radius:12px;
  transition:box-shadow .15s,transform .15s;
}
.pcd-leg-row:hover {
  box-shadow:0 3px 12px rgba(0,0,0,0.07);
  transform:translateX(2px);
}

/* Avatar */
.pcd-leg-av {
  width:32px; height:32px; border-radius:9px;
  display:flex; align-items:center; justify-content:center;
  font-size:13px; font-weight:900; color:#fff;
  box-shadow:0 2px 6px rgba(0,0,0,0.16); flex-shrink:0;
}

/* Name + phase */
.pcd-leg-meta  { min-width:0; }
.pcd-leg-name  {
  font-size:12px; font-weight:700; color:#1e293b;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  line-height:1.3;
}
.pcd-phase {
  display:inline-flex; align-items:center; gap:2px;
  font-size:9px; font-weight:700;
  padding:2px 6px; border-radius:4px;
  margin-top:2px; white-space:nowrap;
}
.pcd-phase--planning   { background:#ede9fe; color:#7c3aed; }
.pcd-phase--initiating { background:#dbeafe; color:#1d4ed8; }
.pcd-phase--executing  { background:#d1fae5; color:#059669; }
.pcd-phase--closing    { background:#fef3c7; color:#d97706; }
.pcd-phase--none       { background:#f1f5f9; color:#64748b; }

/* Inline bar */
.pcd-leg-bar-wrap { min-width:0; }
.pcd-leg-bar-track {
  height:8px; background:#f1f5f9;
  border-radius:99px; overflow:hidden;
}
.pcd-leg-bar-fill {
  height:100%; border-radius:99px;
  position:relative; overflow:hidden;
  transition:width 1.5s cubic-bezier(.34,1.56,.64,1);
}
.pcd-bar-shine {
  position:absolute; inset:0;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);
  animation:pcdShine 2.8s ease-in-out infinite;
}
@keyframes pcdShine {
  0%   { transform:translateX(-100%); }
  100% { transform:translateX(300%); }
}

/* Percent + dot */
.pcd-leg-right {
  display:flex; align-items:center; justify-content:flex-end; gap:6px;
  flex-shrink:0;
}
.pcd-leg-pct {
  font-size:14px; font-weight:900; white-space:nowrap;
}
.pcd-status-dot {
  width:8px; height:8px; border-radius:50%; flex-shrink:0;
  box-shadow:0 0 0 2px rgba(255,255,255,0.9);
}

/* ── Empty ── */
.pcd-empty     { padding:40px 20px; text-align:center; }
.pcd-empty-ico {
  width:48px; height:48px; border-radius:14px; background:#f1f5f9;
  display:flex; align-items:center; justify-content:center;
  font-size:20px; color:#94a3b8; margin:0 auto 12px;
}
.pcd-empty p    { font-size:13px; font-weight:700; color:#475569; margin:0 0 4px; }
.pcd-empty span { font-size:11px; color:#94a3b8; }

/* ── Responsive ── */
@media (max-width:480px) {
  .pcd-kpi-strip { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .pcd-leg-row   { grid-template-columns:32px 1fr 80px 44px; gap:7px; }
  .pcd-hd-pills  { display:none; }
}
@media (max-width:360px) {
  .pcd-leg-row { grid-template-columns:32px 1fr 44px; }
  .pcd-leg-bar-wrap { display:none; }
}


/* ════════════════════════════════════════
   REIMBURSEMENTS — v3
════════════════════════════════════════ */
.gn-rb-kpi-strip { display: flex; border-bottom: 1px solid #f1f5f9; }
.gn-rb-kpi {
  flex: 1; display: flex; align-items: center; gap: 10px;
  padding: 14px 16px; border-right: 1px solid #f1f5f9;
  transition: background 0.15s; cursor: default;
}
.gn-rb-kpi:last-child { border-right: none; }
.gn-rb-kpi:hover { background: #f8fafc; }
.gn-rb-kpi-icon { width: 36px; height: 36px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 14px; flex-shrink: 0; }
.gn-rb-kpi--indigo .gn-rb-kpi-icon { background: rgba(99,102,241,0.1);  color: #6366f1; }
.gn-rb-kpi--green  .gn-rb-kpi-icon { background: rgba(16,185,129,0.1); color: #10b981; }
.gn-rb-kpi--amber  .gn-rb-kpi-icon { background: rgba(245,158,11,0.1);  color: #d97706; }
.gn-rb-kpi-info strong { display: block; font-size: 22px; font-weight: 800; line-height: 1; color: #1e1e2e; }
.gn-rb-kpi--indigo .gn-rb-kpi-info strong { color: #6366f1; }
.gn-rb-kpi-info span { font-size: 10px; font-weight: 600; color: #9ca3af; margin-top: 2px; display: block; }
.gn-rb-center { display: flex; gap: 20px; padding: 18px 20px 20px; align-items: flex-start; }
.gn-rb-donut-col { display: flex; flex-direction: column; align-items: center; gap: 10px; flex-shrink: 0; background: #f8fafc; border-radius: 16px; padding: 16px; border: 1px solid #ebebf5; }
.gn-rb-section-lbl { font-size: 10px; font-weight: 700; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.6px; align-self: flex-start; display: flex; align-items: center; gap: 5px; }
.gn-rb-stat-grid { flex: 1; display: grid; grid-template-columns: repeat(2,1fr); gap: 10px; align-content: start; }
.gn-rb-stat-card { background: #f8fafc; border-radius: 14px; border: 1px solid #ebebf5; border-top: 3px solid transparent; padding: 12px 14px; display: flex; align-items: center; gap: 12px; transition: box-shadow 0.15s, transform 0.15s; cursor: default; }
.gn-rb-stat-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.08); transform: translateY(-2px); }
.gn-rb-ring-svg  { width: 44px; height: 44px; flex-shrink: 0; }
.gn-rb-ring-fill { transition: stroke-dashoffset 1.4s cubic-bezier(0.4,0,0.2,1); }
.gn-rb-sc-info   { display: flex; flex-direction: column; gap: 2px; }
.gn-rb-sc-count  { font-size: 24px; font-weight: 900; line-height: 1; }
.gn-rb-sc-name   { font-size: 11px; font-weight: 600; color: #6b7280; }
.gn-rb-total-card { background: linear-gradient(135deg,#EEEDFB,#dddaf7); border-radius: 12px; padding: 12px 16px; display: flex; justify-content: space-between; align-items: center; border: 1px solid #c4bff5; }
.gn-rb-total-lbl  { font-size: 12px; font-weight: 600; color: #5443AD; display: flex; align-items: center; gap: 6px; }
.gn-rb-total-val  { font-size: 28px; font-weight: 900; color: #5443AD; line-height: 1; }
/* ════════════════════════════════════════
   PROJECT STATUS HEALTH  ·  v4  (flat CSS)
════════════════════════════════════════ */

/* ── Shared card title ─────────────────── */
.psh-card-title {
  font-size: 10px;
  font-weight: 700;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 14px;
}
.psh-card-title i { color: #9ca3af; }
.psh-card-sub {
  font-size: 10px;
  font-weight: 500;
  color: #9ca3af;
  text-transform: none;
  letter-spacing: 0;
  margin-left: 6px;
}

/* ── Shared dot ────────────────────────── */
.psh-dot {
  display: inline-block;
  width: 8px; height: 8px;
  border-radius: 2px;
  margin-right: 3px;
  vertical-align: middle;
  font-style: normal;
}
.psh-dot--g { background: #10b981; }
.psh-dot--y { background: #f59e0b; }
.psh-dot--r { background: #ef4444; }

/* ══ ROW 1: top row ═══════════════════════ */
.psh-top-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 16px;
  align-items: stretch;
  margin-bottom: 18px;
}

/* 3 pill KPIs */
.psh-pill-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.psh-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1.5px solid transparent;
  min-width: 160px;
  cursor: default;
  transition: transform 0.15s, box-shadow 0.15s;
}
.psh-pill:hover {
  transform: translateX(3px);
  box-shadow: 0 4px 14px rgba(0,0,0,0.09);
}
.psh-pill--g {
  background: linear-gradient(135deg,#f0fdf4,#dcfce7);
  border-color: #bbf7d0;
}
.psh-pill--y {
  background: linear-gradient(135deg,#fffbeb,#fef3c7);
  border-color: #fde68a;
}
.psh-pill--r {
  background: linear-gradient(135deg,#fef2f2,#fee2e2);
  border-color: #fca5a5;
}
.psh-pill--g > i { font-size: 20px; color: #16a34a; }
.psh-pill--y > i { font-size: 20px; color: #d97706; }
.psh-pill--r > i { font-size: 20px; color: #dc2626; }

.psh-pill-body { flex: 1; }
.psh-pill-body strong { display: block; font-size: 24px; font-weight: 900; line-height: 1; }
.psh-pill--g .psh-pill-body strong { color: #16a34a; }
.psh-pill--y .psh-pill-body strong { color: #d97706; }
.psh-pill--r .psh-pill-body strong { color: #dc2626; }
.psh-pill-body span { font-size: 10px; font-weight: 600; color: #6b7280; }

.psh-pill-pct { font-size: 12px; font-weight: 800; }
.psh-pill--g .psh-pill-pct { color: #16a34a; }
.psh-pill--y .psh-pill-pct { color: #d97706; }
.psh-pill--r .psh-pill-pct { color: #dc2626; }

/* Score bar card */
.psh-score-card {
  background: #fafbff;
  border: 1px solid #f1f5f9;
  border-radius: 14px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
}
.psh-score-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 11px;
  font-weight: 700;
  color: #374151;
}
.psh-score-label strong {
  font-size: 28px;
  font-weight: 900;
  color: #10b981;
  line-height: 1;
}
.psh-score-track {
  height: 18px;
  background: #f1f5f9;
  border-radius: 99px;
  overflow: hidden;
  display: flex;
  gap: 2px;
}
.psh-score-seg {
  height: 100%;
  border-radius: 99px;
  transition: width 1.4s cubic-bezier(0.4,0,0.2,1);
}
.psh-score-seg--r { background: linear-gradient(90deg,#dc2626,#ef4444); }
.psh-score-seg--y { background: linear-gradient(90deg,#d97706,#f59e0b); }
.psh-score-seg--g { background: linear-gradient(90deg,#059669,#10b981); }
.psh-score-legend {
  display: flex;
  gap: 16px;
  font-size: 11px;
  font-weight: 600;
  color: #6b7280;
}

/* ══ ROW 2: mid row ═══════════════════════ */
.psh-mid-row {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 16px;
  margin-bottom: 18px;
}
.psh-dims-card,
.psh-radar-card {
  background: #fafbff;
  border: 1px solid #f1f5f9;
  border-radius: 14px;
  padding: 16px 18px;
}

/* Dimension bar list */
.psh-dim-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.psh-dim-item {
  display: flex;
  align-items: center;
  gap: 10px;
}
.psh-dim-ico-wrap {
  width: 28px; height: 28px;
  border-radius: 8px;
  background: #EEEDFB;
  color: #5443AD;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  flex-shrink: 0;
}
.psh-dim-name {
  width: 70px;
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
  color: #374151;
}
.psh-dim-bar-wrap { flex: 1; min-width: 0; }
.psh-dim-bar-bg {
  height: 28px;
  background: #f1f5f9;
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  gap: 2px;
}
.psh-db-seg {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 800;
  color: #fff;
  text-shadow: 0 1px 2px rgba(0,0,0,0.25);
  transition: width 1.3s cubic-bezier(0.4,0,0.2,1);
  overflow: hidden;
  min-width: 0;
}
.psh-db-seg span { padding: 0 4px; white-space: nowrap; }
.psh-db-g { background: linear-gradient(90deg,#059669,#10b981); }
.psh-db-y { background: linear-gradient(90deg,#d97706,#f59e0b); }
.psh-db-r { background: linear-gradient(90deg,#dc2626,#ef4444); }
.psh-db-empty {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: #9ca3af;
  font-weight: 500;
}

/* mini badges */
.psh-dim-badges { display: flex; gap: 4px; flex-shrink: 0; }
.psh-mb {
  font-size: 10px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 6px;
  min-width: 22px;
  text-align: center;
}
.psh-mb--g { background: #dcfce7; color: #16a34a; }
.psh-mb--y { background: #fef3c7; color: #d97706; }
.psh-mb--r { background: #fee2e2; color: #dc2626; }

/* bar legend */
.psh-bar-legend {
  display: flex;
  gap: 14px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid #f1f5f9;
}
.psh-bl-item {
  font-size: 10px;
  font-weight: 600;
  color: #6b7280;
  display: flex;
  align-items: center;
  gap: 4px;
}
.psh-agg-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  justify-content: center;
}

/* ══ ROW 3: heat matrix ═══════════════════ */
.psh-grid-section { border-top: 1px solid #f1f5f9; padding-top: 16px; }

.psh-matrix-wrap {
  overflow-x: auto;
  border-radius: 12px;
  border: 1px solid #f1f5f9;
}
.psh-matrix {
  width: 100%;
  min-width: 600px;
  border-collapse: collapse;
  font-size: 12px;
}
.psh-matrix thead tr {
  background: #f8fafc;
}
.psh-mth {
  padding: 9px 12px;
  text-align: left;
  font-size: 9px;
  font-weight: 700;
  color: #9ca3af;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid #f1f5f9;
  white-space: nowrap;
}
.psh-mth i { margin-right: 4px; }
.psh-mth--project { width: 200px; }
.psh-mth--reports { width: 90px; text-align: center; }

.psh-mtd {
  padding: 9px 12px;
  border-bottom: 1px solid #f9fafb;
  vertical-align: middle;
}

.psh-mrow { transition: background 0.14s; cursor: default; }
.psh-mrow:hover td { background: #f8fafc !important; }
.psh-mrow:last-child td { border-bottom: none; }

/* row left accent via box-shadow on first td trick */
.psh-mrow--g { border-left: 3px solid #10b981; }
.psh-mrow--y { border-left: 3px solid #f59e0b; }
.psh-mrow--r { border-left: 3px solid #ef4444; }

/* project cell */
.psh-mtd--project {
  display: flex;
  align-items: center;
  gap: 8px;
}
.psh-mav {
  width: 28px; height: 28px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 900;
  flex-shrink: 0;
}
.psh-mname-wrap { min-width: 0; }
.psh-mname {
  font-size: 11px; font-weight: 700; color: #111827;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 150px;
}
.psh-mnum {
  font-size: 9px; font-weight: 700; color: #5443AD;
  background: #EEEDFB; padding: 1px 5px; border-radius: 4px;
  display: inline-block; margin-top: 2px;
}

/* health cells */
.psh-mtd--health { text-align: center; }

.psh-hcell {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 9px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 20px;
  white-space: nowrap;
}
.psh-hcell i { font-size: 8px; }
.psh-hcell--green  { background: #dcfce7; color: #16a34a; }
.psh-hcell--yellow { background: #fef3c7; color: #b45309; }
.psh-hcell--red    { background: #fee2e2; color: #dc2626; }
.psh-hcell--none   { background: #f1f5f9; color: #9ca3af; }

/* reports cell */
.psh-mtd--reports { text-align: center; }
.psh-rcount {
  display: block;
  font-size: 11px; font-weight: 800; color: #5443AD;
}
.psh-rcount i { margin-right: 2px; }
.psh-rdate {
  display: block;
  font-size: 9px; color: #9ca3af; margin-top: 2px;
}

/* ── Responsive ─────────────────────────── */
@media (max-width: 900px) {
  .psh-mid-row { grid-template-columns: 1fr; }
  .psh-radar-card { display: none; }
}
@media (max-width: 640px) {
  .psh-top-row { grid-template-columns: 1fr; }
  .psh-pill-group { flex-direction: row; flex-wrap: wrap; }
  .psh-pill { min-width: 0; flex: 1; }
}

/* ════════════════════════════════════════
   PROGRESS LEGEND
════════════════════════════════════════ */
.gn-progress-legend { display: flex; gap: 16px; flex-wrap: wrap; margin-top: 14px; padding-top: 14px; border-top: 1px solid #f1f5f9; }
.gn-plg         { font-size: 11px; font-weight: 600; display: flex; align-items: center; gap: 5px; }
.gn-plg--green  { color: #10b981; }
.gn-plg--amber  { color: #f59e0b; }
.gn-plg--red    { color: #ef4444; }

/* ════════════════════════════════════════
   DONUT LAYOUT
════════════════════════════════════════ */
.gn-donut-layout { display: flex; gap: 24px; align-items: center; flex-wrap: wrap; }
.gn-rich-legend  { flex: 1; display: flex; flex-direction: column; gap: 10px; min-width: 140px; }
.gn-rich-legend-item { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; background: #f8fafc; border-radius: 10px; border: 1px solid #f1f5f9; transition: background 0.15s; }
.gn-rich-legend-item:hover { background: #f0f2f8; }
.gn-rich-legend-left { display: flex; align-items: center; gap: 8px; }
.gn-rich-dot   { width: 12px; height: 12px; border-radius: 3px; flex-shrink: 0; }
.gn-rich-label { font-size: 12px; color: #374151; font-weight: 500; }
.gn-rich-right { display: flex; align-items: center; gap: 8px; }
.gn-rich-count { font-size: 15px; font-weight: 800; }
.gn-rich-pct   { font-size: 11px; color: #9ca3af; font-weight: 500; }

/* ════════════════════════════════════════
   STATUS REPORTS
════════════════════════════════════════ */
.gn-sr-toprow   { display: flex; gap: 12px; margin-bottom: 16px; }
.gn-sr-stat     { flex: 1; background: #f8fafc; border-radius: 10px; padding: 10px 12px; border: 1px solid #f1f5f9; text-align: center; }
.gn-sr-stat-val { font-size: 22px; font-weight: 800; color: #f43f5e; line-height: 1; }
.gn-sr-stat-lbl { font-size: 11px; color: #9ca3af; font-weight: 500; margin-top: 3px; }

/* ════════════════════════════════════════
   CHANGE REQUESTS
════════════════════════════════════════ */
.gn-cr-charts           { display: flex; gap: 20px; margin-bottom: 20px; flex-wrap: wrap; }
.gn-cr-chart-block      { flex: 0 0 auto; }
.gn-cr-chart-block--bar { flex: 1; min-width: 160px; }
.gn-cr-chart-title      { font-size: 11px; font-weight: 700; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 10px; }
.gn-cr-donut-wrap   { display: flex; gap: 14px; align-items: center; }
.gn-cr-donut-legend { display: flex; flex-direction: column; gap: 7px; min-width: 120px; }
.gn-cr-legend-row   { display: flex; align-items: center; gap: 7px; font-size: 12px; }
.gn-cr-dot  { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
.gn-cr-lbl  { flex: 1; color: #374151; font-weight: 500; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gn-cr-cnt  { font-size: 13px; font-weight: 800; flex-shrink: 0; }
.gn-cr-table-wrap  { border-top: 1px solid #f1f5f9; padding-top: 16px; }
.gn-cr-table-title { font-size: 11px; font-weight: 700; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 10px; }
.gn-cr-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.gn-cr-table thead tr { background: #f8fafc; }
.gn-cr-table th { text-align: left; padding: 8px 10px; font-size: 11px; font-weight: 700; color: #9ca3af; text-transform: uppercase; letter-spacing: 0.4px; border-bottom: 1px solid #f1f5f9; }
.gn-cr-table td  { padding: 9px 10px; border-bottom: 1px solid #f9fafb; vertical-align: middle; }
.gn-cr-table tbody tr:last-child td { border-bottom: none; }
.gn-cr-table tbody tr:hover td      { background: #f8fafc; }
.gn-cr-num   { font-size: 11px; font-weight: 700; color: #5443AD; background: #EEEDFB; padding: 3px 8px; border-radius: 6px; white-space: nowrap; }
.gn-cr-desc  { color: #1e1e2e; font-weight: 500; max-width: 160px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gn-cr-tag       { font-size: 11px; font-weight: 600; padding: 3px 9px; border-radius: 20px; white-space: nowrap; }
.gn-cr-tag--blue { background: #EEEDFB; color: #5443AD; }
.gn-cr-pri       { font-size: 11px; font-weight: 700; padding: 3px 9px; border-radius: 20px; white-space: nowrap; }
.gn-pri-critical { background: #fee2e2; color: #dc2626; }
.gn-pri-high     { background: #fef3c7; color: #b45309; }
.gn-pri-medium   { background: #e0f2fe; color: #0369a1; }
.gn-pri-low      { background: #f0fdf4; color: #16a34a; }
.gn-cr-state     { font-size: 11px; font-weight: 600; color: #6b7280; background: #f1f5f9; padding: 3px 9px; border-radius: 20px; }

/* ════════════════════════════════════════
   EMPTY STATE
════════════════════════════════════════ */
.gn-empty-fancy { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 48px 20px; color: #d1d5db; gap: 12px; }
.gn-empty-fancy i { font-size: 40px; }
.gn-empty-fancy p { font-size: 13px; color: #9ca3af; margin: 0; }

/* ════════════════════════════════════════
   RESPONSIVE
════════════════════════════════════════ */
@media (max-width: 1100px) {
  .gn-cards          { grid-template-columns: repeat(2,1fr); }
  .gn-ap-kpi-row     { grid-template-columns: repeat(2,1fr); }
  .gn-pc-kpi-strip   { grid-template-columns: repeat(2,1fr); }
}
@media (max-width: 1000px) {
  .gn-psh-top   { flex-direction: column; }
  .gn-psh-right { width: 100%; }
}
@media (max-width: 960px) {
  .gn-pc-main        { flex-direction: column; }
  .gn-pc-polar-block { width: 100%; }
  .gn-rb-center      { flex-direction: column; align-items: stretch; }
  .gn-rb-donut-col   { align-items: center; }
}
@media (max-width: 860px) {
  .gn-grid                             { grid-template-columns: 1fr; }
  .gn-cards                            { grid-template-columns: repeat(2,1fr); }
  .gn-donut-layout                     { flex-direction: column; }
  .gn-analytics-body.gn-pipeline-body { flex-direction: column; }
  .gn-pipeline-stats                   { width: 100%; }
  .gn-cr-charts                        { flex-direction: column; }
  .gn-cr-chart-block--bar              { min-width: 100%; }
  .gn-ap-mid                           { flex-direction: column; }
  .gn-ap-donut-wrap                    { width: 100%; }
  .gn-ap-donut-inner                   { flex-direction: column; align-items: center; }
  .gn-ap-funnel-meta                   { width: 110px; }
  .gn-ps-kpi-strip                     { gap: 6px; }
  .gn-ps-kpi strong                    { font-size: 22px; }
  .gn-ps-dim-label                     { width: 72px; font-size: 11px; }
}
@media (max-width: 600px) {
  .gn-cards          { grid-template-columns: 1fr; }
  .gn-main           { padding: 16px; }
  .gn-banner         { padding: 28px 24px 24px; }
  .gn-ap-kpi-row     { grid-template-columns: repeat(2,1fr); }
  .gn-ap-kpi         { padding: 12px; }
  .gn-ap-kpi-info strong { font-size: 22px; }
  .gn-ap-hdr-stat    { display: none; }
  .gn-ap-conv-label  { font-size: 9px; }
  .gn-ap-conv-val    { font-size: 16px; }
  .gn-pc-kpi-strip   { grid-template-columns: repeat(2,1fr); }
  .gn-pc-hdr-pill    { display: none; }
  .gn-rb-stat-grid   { grid-template-columns: 1fr; }
  .gn-ps-kpi span    { display: none; }
  .gn-ps-dim-label   { width: 58px; font-size: 10px; }
  .gn-ps-table th:nth-child(n+3),
  .gn-ps-table td:nth-child(n+3) { display: none; }
}

sp_widget.link:
function link(scope, element, attrs, controller) {
  // Load Chart.js dynamically if not already loaded
  if (typeof Chart === 'undefined') {
    var script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
    script.onload = function() {
      // Chart.js is now ready — trigger the draw
      scope.$apply(function() {
        scope.$$childHead && scope.$$childHead.drawCharts 
          ? scope.$$childHead.drawCharts() 
          : null;
      });
    };
    document.head.appendChild(script);
  }
}

sp_widget.script:
(function() {
  data.sideBar = $sp.getWidget('sidebar_dashboard');
  var userId   = gs.getUserID();
  var userName = gs.getUserDisplayName();

  data.user = { name: userName || 'User', sys_id: userId || '' };
  data.totalApplications = 0;
  data.newThisMonth      = 0;
  data.pendingAwards     = 0;
  data.activeProjects    = 0;

  // ══════════════════════════════════════════════════════
  // TOTAL APPLICATIONS
  // ══════════════════════════════════════════════════════
  try {
    var appGR = new GlideRecordSecure('x_enno_gatenow_service_applicants');
    appGR.addQuery('sys_created_by', gs.getUserName());
    appGR.query();
    while (appGR.next()) { data.totalApplications++; }
  } catch(e) { gs.debug('Dashboard-totalApps: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // NEW THIS MONTH
  // ══════════════════════════════════════════════════════
  try {
    var monthAgo = new GlideDateTime();
    monthAgo.addMonthsLocalTime(-1);
    var newGR = new GlideRecordSecure('x_enno_gatenow_service_applicants');
    newGR.addQuery('sys_created_by', gs.getUserName());
    newGR.addQuery('sys_created_on', '>=', monthAgo.getValue());
    newGR.query();
    while (newGR.next()) { data.newThisMonth++; }
  } catch(e) { gs.debug('Dashboard-newThisMonth: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // ACTIVE PROJECTS  (KPI counter)
  // ══════════════════════════════════════════════════════
  try {
    var projectGR = new GlideRecordSecure('x_enno_gatenow_project');
    projectGR.addActiveQuery();
    projectGR.addQuery('x_enno_gatenow_applicant.user', userId);
    projectGR.query();
    while (projectGR.next()) { data.activeProjects++; }
  } catch(e) { gs.debug('Dashboard-activeProjects: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // APPLICANT sys_ids  (for awards query)
  // ══════════════════════════════════════════════════════
  var applicantIds = [];
  try {
    var applicantGR = new GlideRecordSecure('x_enno_gatenow_service_applicants');
    applicantGR.addQuery('user', userId);
    applicantGR.query();
    while (applicantGR.next()) {
      applicantIds.push(applicantGR.getUniqueValue());
    }
  } catch(e) { gs.debug('Dashboard-applicantIds: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // PENDING AWARDS
  // ══════════════════════════════════════════════════════
  if (applicantIds.length > 0) {
    try {
      var pendingGR = new GlideRecordSecure('x_enno_gatenow_grant_awards');
      pendingGR.addQuery('applicant', 'IN', applicantIds.join(','));
      pendingGR.addQuery('applicant_response', 'Pending');
      pendingGR.query();
      while (pendingGR.next()) { data.pendingAwards++; }
    } catch(e) { gs.debug('Dashboard-pendingAwards: ' + e.message); }
  }

  // ══════════════════════════════════════════════════════
  // PROJECT sys_ids  (shared base for all sub-queries)
  // ══════════════════════════════════════════════════════
  var projectIds = [];
  try {
    var pidGR = new GlideRecordSecure('pm_project');
    pidGR.addActiveQuery();
    pidGR.addQuery('x_enno_gatenow_applicant.user', userId);
    pidGR.query();
    while (pidGR.next()) {
      projectIds.push(pidGR.getUniqueValue());
    }
  } catch(e) { gs.debug('Dashboard-projectIds: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // APPLICATION STATUS CHART  (vertical bar)
  // ══════════════════════════════════════════════════════
  data.appStatusChart = { labels: [], counts: [] };
  try {
    var statusMap = {};
    var statusGR = new GlideRecordSecure('x_enno_gatenow_service_applicants');
    statusGR.addQuery('sys_created_by', gs.getUserName());
    statusGR.query();
    while (statusGR.next()) {
      var lbl = statusGR.getDisplayValue('state') || 'Unknown';
      statusMap[lbl] = (statusMap[lbl] || 0) + 1;
    }
    for (var s in statusMap) {
      data.appStatusChart.labels.push(s);
      data.appStatusChart.counts.push(statusMap[s]);
    }
  } catch(e) { gs.debug('Dashboard-appStatus: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // PROJECT STATUS HEALTH  (5 dimensions per report)
  // Table  : project_status
  // Link   : project → pm_project
  // Fields : overall_health | schedule | cost | resources | scope
  // Values : Green(1) | Yellow(2) | Red(3) | None → green
  // ══════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════
// PROJECT STATUS HEALTH  (5 dimensions per report)
// ══════════════════════════════════════════════════════
data.projectStatusData = {
  projects:     [],
  summary:      { green: 0, yellow: 0, red: 0 },
  dimensions:   [],
  totalReports: 0
};

try {
  if (projectIds.length > 0) {

    var dimCounts = {
      overall_health: { green: 0, yellow: 0, red: 0 },
      schedule:       { green: 0, yellow: 0, red: 0 },
      cost:           { green: 0, yellow: 0, red: 0 },
      resources:      { green: 0, yellow: 0, red: 0 },
      scope:          { green: 0, yellow: 0, red: 0 }
    };

    function normaliseHealth(raw) {
      if (!raw) return 'green';
      var v = (raw + '').toLowerCase().trim();
      if (v === 'red'    || v === '3') return 'red';
      if (v === 'yellow' || v === '2') return 'yellow';
      return 'green';
    }

    // Map: projectSysId → { name, number, counts per dimension }
    var projectMap = {};

    var psGR = new GlideRecordSecure('project_status');
    psGR.addQuery('project', 'IN', projectIds.join(','));
    psGR.orderByDesc('sys_created_on');
    psGR.query();

    while (psGR.next()) {
      data.projectStatusData.totalReports++;

      var projId  = psGR.getValue('project');
      var projName = (psGR.getDisplayValue('project') || 'Unnamed').substring(0, 34);
      var projNum  = psGR.getValue('number') || '';

      var oh  = normaliseHealth(psGR.getDisplayValue('overall_health'));
      var sch = normaliseHealth(psGR.getDisplayValue('schedule'));
      var cst = normaliseHealth(psGR.getDisplayValue('cost'));
      var res = normaliseHealth(psGR.getDisplayValue('resources'));
      var scp = normaliseHealth(psGR.getDisplayValue('scope'));

      // Init project entry if first time seeing this project
      if (!projectMap[projId]) {
        projectMap[projId] = {
          name:   projName,
          number: projNum,
          reportCount: 0,
          overall_health: { green: 0, yellow: 0, red: 0 },
          schedule:       { green: 0, yellow: 0, red: 0 },
          cost:           { green: 0, yellow: 0, red: 0 },
          resources:      { green: 0, yellow: 0, red: 0 },
          scope:          { green: 0, yellow: 0, red: 0 }
        };
      }

      // Aggregate counts per project per dimension
      projectMap[projId].reportCount++;
      projectMap[projId].overall_health[oh]++;
      projectMap[projId].schedule[sch]++;
      projectMap[projId].cost[cst]++;
      projectMap[projId].resources[res]++;
      projectMap[projId].scope[scp]++;

      // Global dimension tallies (for stacked bars)
      dimCounts.overall_health[oh]++;
      dimCounts.schedule[sch]++;
      dimCounts.cost[cst]++;
      dimCounts.resources[res]++;
      dimCounts.scope[scp]++;

      // Global summary — based on overall_health across all reports
      data.projectStatusData.summary[oh]++;
    }

    // Convert projectMap to array
    for (var pid in projectMap) {
      var p = projectMap[pid];

      // Dominant color = whichever has the most reports per dimension
      function dominant(dim) {
        if (dim.red >= dim.yellow && dim.red >= dim.green)    return 'red';
        if (dim.yellow >= dim.green)                           return 'yellow';
        return 'green';
      }

      data.projectStatusData.projects.push({
        name:        p.name,
        number:      p.number,
        reportCount: p.reportCount,
        // Dominant health per dimension (for row accent color)
        overall_health: dominant(p.overall_health),
        schedule:       dominant(p.schedule),
        cost:           dominant(p.cost),
        resources:      dominant(p.resources),
        scope:          dominant(p.scope),
        // Raw counts per dimension for mini-badges in cells
        overall_counts:  p.overall_health,
        schedule_counts: p.schedule,
        cost_counts:     p.cost,
        resources_counts:p.resources,
        scope_counts:    p.scope
      });
    }

    // Build dimension array for bars + radar
    var dimMeta = [
      { key: 'overall_health', label: 'Overall'  },
      { key: 'schedule',       label: 'Schedule' },
      { key: 'cost',           label: 'Cost'     },
      { key: 'resources',      label: 'Resources'},
      { key: 'scope',          label: 'Scope'    }
    ];
    for (var di = 0; di < dimMeta.length; di++) {
      var dKey = dimMeta[di].key;
      data.projectStatusData.dimensions.push({
        key:    dKey,
        label:  dimMeta[di].label,
        green:  dimCounts[dKey].green,
        yellow: dimCounts[dKey].yellow,
        red:    dimCounts[dKey].red
      });
    }
  }
} catch(e) { gs.debug('Dashboard-projectStatus: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // PROJECT PROGRESS  (percent_complete horizontal bars)
  // Kept — used by countProjects() helper in client script
  // ══════════════════════════════════════════════════════
// PROJECT PROGRESS
data.projectProgress = [];
try {
  var ppGR = new GlideRecordSecure('pm_project');
  ppGR.addActiveQuery();
  ppGR.addQuery('x_enno_gatenow_applicant.user', userId);
  ppGR.setLimit(8);
  ppGR.query();
  while (ppGR.next()) {
    var pName   = ppGR.getValue('short_description') || ppGR.getValue('name') || 'Project';
    var pPct    = parseInt(ppGR.getValue('percent_complete') || 0);
    var pNum    = ppGR.getValue('number')            || '';
    var pPhase  = ppGR.getDisplayValue('phase')      || '';
    data.projectProgress.push({
      name:    pName.substring(0, 40),
      number:  pNum,
      phase:   pPhase,
      percent: pPct
    });
  }
} catch(e) { gs.debug('Dashboard-projectProgress: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // REIMBURSEMENT STATS  (doughnut)
  // Table : x_enno_gatenow_reimbursement
  // Link  : project → pm_project
  // ══════════════════════════════════════════════════════
  data.reimbursementStats = { total: 0, items: [] };
  try {
    if (projectIds.length > 0) {
      var rMap = {};
      var rGR  = new GlideRecordSecure('x_enno_gatenow_reimbursement');
      rGR.addQuery('parent', 'IN', projectIds.join(','));
      rGR.query();
      while (rGR.next()) {
        var rl = rGR.getDisplayValue('status') || 'Unknown';
        rMap[rl] = (rMap[rl] || 0) + 1;
        data.reimbursementStats.total++;
      }
      var rColors = ['#5443AD','#10b981','#f59e0b','#ef4444','#6366f1','#06b6d4'];
      var ri = 0;
      for (var rk in rMap) {
        data.reimbursementStats.items.push({ label: rk, count: rMap[rk], color: rColors[ri % rColors.length] });
        ri++;
      }
    }
  } catch(e) { gs.debug('Dashboard-reimbursements: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // CHANGE REQUEST STATS  (priority doughnut + category
  //   horizontal bar + recent-records table)
  // Table : project_change_request
  // Link  : parent → pm_project
  // ══════════════════════════════════════════════════════
  data.changeRequestStats = { total: 0, byPriority: [], byCategory: [], items: [], donutItems: [] };
  try {
    if (projectIds.length > 0) {
      var priorityMap = {};
      var categoryMap = {};
      var crList      = [];

      var crGR = new GlideRecordSecure('project_change_request');
      crGR.addQuery('parent', 'IN', projectIds.join(','));
      crGR.orderByDesc('sys_created_on');
      crGR.query();

      while (crGR.next()) {
        var crNum  = crGR.getValue('number')                   || '—';
        var crName = crGR.getDisplayValue('short_description') || 'Change Request';
        var crSt   = crGR.getDisplayValue('state')             || 'Open';
        var crPri  = crGR.getDisplayValue('priority')          || 'Unknown';
        var crCat  = crGR.getDisplayValue('category')          || 'General';

        crList.push({ number: crNum, name: crName.substring(0, 40), state: crSt, priority: crPri, category: crCat });
        priorityMap[crPri] = (priorityMap[crPri] || 0) + 1;
        categoryMap[crCat] = (categoryMap[crCat] || 0) + 1;
        data.changeRequestStats.total++;
      }

      var priColors = {
        '1 - Critical': '#ef4444', 'Critical':  '#ef4444',
        '2 - High':     '#f59e0b', 'High':      '#f59e0b',
        '3 - Moderate': '#06b6d4', 'Moderate':  '#06b6d4',
        '4 - Low':      '#10b981', 'Low':       '#10b981'
      };
      var catColors = ['#5443AD','#10b981','#f59e0b','#ef4444','#06b6d4','#8b5cf6','#f43f5e'];

      var piIdx = 0;
      for (var pk in priorityMap) {
        data.changeRequestStats.byPriority.push({ label: pk, count: priorityMap[pk], color: priColors[pk] || catColors[piIdx % catColors.length] });
        piIdx++;
      }
      data.changeRequestStats.byPriority.sort(function(a, b) { return b.count - a.count; });

      var ciIdx = 0;
      for (var ck in categoryMap) {
        data.changeRequestStats.byCategory.push({ label: ck, count: categoryMap[ck], color: catColors[ciIdx % catColors.length] });
        ciIdx++;
      }

      data.changeRequestStats.items      = crList.slice(0, 5);
      data.changeRequestStats.donutItems = data.changeRequestStats.byPriority;
    }
  } catch(e) { gs.debug('Dashboard-changeRequests: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // STATUS REPORTS BY MONTH  (area line chart)
  // Table : project_status  |  Link: project → pm_project
  // ══════════════════════════════════════════════════════
  data.statusReports = [];
  try {
    if (projectIds.length > 0) {
      var srMap = {};
      var srGR  = new GlideRecordSecure('project_status');
      srGR.addQuery('project', 'IN', projectIds.join(','));
      srGR.orderBy('sys_created_on');
      srGR.query();
      while (srGR.next()) {
        var dt  = new GlideDateTime(srGR.getValue('sys_created_on'));
        var mon = dt.getMonthLocalTime() + '/' + dt.getYearLocalTime();
        srMap[mon] = (srMap[mon] || 0) + 1;
      }
      for (var mk in srMap) {
        data.statusReports.push({ month: mk, count: srMap[mk] });
      }
    }
  } catch(e) { gs.debug('Dashboard-statusReports: ' + e.message); }

  // ══════════════════════════════════════════════════════
  // PORTAL URL
  // ══════════════════════════════════════════════════════
  try {
    var portalGR = $sp.getPortalRecord();
    data.portalSuffix = portalGR ? ('/' + portalGR.getValue('url_suffix')) : '/applicant';
  } catch(e) { data.portalSuffix = '/applicant'; }

})();
